export type Runner = Readonly<{readonly "runnerId": Uuid; readonly "responsiblePitcherId": Uuid; readonly "base": ("1" | "2" | "3"); readonly "status": "継続"; readonly "statusSource": "auto"}>;
export type Responsibility = Readonly<{readonly "kind": "no-change"; readonly "paStartSource": Readonly<{readonly "kind": ("started-game" | "confirmed-play"); readonly "id": Uuid}>; readonly "previousPitcherId": null; readonly "strikesAtChange": null; readonly "ballsAtChange": null}>;
export type Slot = ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9");
export type LineupTeam = Readonly<{readonly "teamId": Uuid; readonly "battingOrder": Readonly<{readonly "1": Uuid; readonly "2": Uuid; readonly "3": Uuid; readonly "4": Uuid; readonly "5": Uuid; readonly "6": Uuid; readonly "7": Uuid; readonly "8": Uuid; readonly "9": Uuid}>; readonly "pitcherId": Uuid; readonly "catcherId": Uuid}>;
