export type Origin = Readonly<{readonly "kind": "started-game"; readonly "eventId": Uuid}>;
export type PrefixRef = Readonly<{readonly "version": "3"; readonly "scope": "play-prefix-v3"; readonly "tenantId": Uuid; readonly "gameId": Uuid; readonly "generation": string; readonly "length": Unsigned; readonly "checkpoint": Checkpoint; readonly "historyVersion": Unsigned; readonly "origin": Origin}>;
export type BoundaryFacts = Readonly<{readonly "beforeInning": Positive; readonly "beforeHalf": ("top" | "bottom"); readonly "beforeOuts": ("0" | "1" | "2"); readonly "afterInning": Positive; readonly "afterHalf": ("top" | "bottom"); readonly "afterOuts": ("0" | "1" | "2"); readonly "halfCompleted": boolean; readonly "outsUnchanged": boolean; readonly "scoreUnchanged": boolean; readonly "priorOpen": true}>;
