export type T2 = Readonly<{readonly "kind": "evaluated-end-condition"; readonly "scope": "play-prefix-v3"; readonly "evaluation_point": "post-play"; readonly "facts": BoundaryFacts; readonly "decision": Decision; readonly "tiebreakStartRequired": boolean}>;
export type SourceProvenance = (Readonly<{readonly "kind": "started-game"; readonly "eventId": Uuid}> | Readonly<{readonly "kind": "confirmed-prefix"; readonly "checkpoint": Checkpoint; readonly "sourceIdentity": PlayIdentity; readonly "historyDepth": Unsigned}>);
export type Source = (Readonly<{readonly "kind": "started-initial-v3"; readonly "prefixRef": PrefixRef; readonly "rules": SavedRuleWire; readonly "after": Snapshot; readonly "t2": null; readonly "historyDepth": "0"; readonly "playCount": "0"; readonly "lastSource": null; readonly "position": Position; readonly "priorArtifactSha256": Digest; readonly "executionArtifactSha256": Digest; readonly "rulesDigest": Digest; readonly "layoutDigest": Digest; readonly "rosterDigest": Digest; readonly "lineup": Lineup; readonly "runners": readonly (Runner)[]; readonly "participants": Participant; readonly "responsibility": Responsibility; readonly "provenance": Readonly<{readonly "kind": "started-game"; readonly "eventId": Uuid}>}> | Readonly<{readonly "kind": ("evaluated-prefix-v3" | "locked-prefix-v3"); readonly "prefixRef": PrefixRef; readonly "rules": SavedRuleWire; readonly "after": Snapshot; readonly "t2": T2; readonly "historyDepth": Unsigned; readonly "playCount": Unsigned; readonly "lastSource": PlayIdentity; readonly "position": Position; readonly "priorArtifactSha256": Digest; readonly "executionArtifactSha256": Digest; readonly "rulesDigest": Digest; readonly "layoutDigest": Digest; readonly "rosterDigest": Digest; readonly "lineup": Lineup; readonly "runners": readonly (Runner)[]; readonly "participants": Participant; readonly "responsibility": Responsibility; readonly "provenance": Readonly<{readonly "kind": "confirmed-prefix"; readonly "checkpoint": Checkpoint; readonly "sourceIdentity": PlayIdentity; readonly "historyDepth": Unsigned}>}>);
