export type Value = Readonly<{readonly "t1": T1; readonly "t2": T2; readonly "newHistoryEntry": HistoryEntry; readonly "previousPrefixRef": PrefixRef; readonly "nextPrefixRef": PrefixRef; readonly "runners": readonly (Runner)[]; readonly "beforeParticipants": Participant; readonly "participants": Participant; readonly "lineup": Lineup; readonly "rosterDigest": Digest; readonly "responsibility": Responsibility; readonly "nextResponsibility": Responsibility; readonly "playIdentity": PlayIdentity; readonly "sourcePosition": Position; readonly "executionArtifactSha256": Digest}>;
